// Team digest: proposals whose follow-up date has arrived, invoices due within 3 days or overdue.

const IST_MS = 330 * 60000;
const dayOf = (v) => {
  if (!v) return null;
  const t = Date.parse(v);
  return Number.isFinite(t) ? new Date(t + IST_MS).toISOString().slice(0, 10) : null;
};
const today = new Date(Date.now() + IST_MS).toISOString().slice(0, 10);
const daysBetween = (a, b) => Math.round((Date.parse(a) - Date.parse(b)) / 864e5);
const nice = (d) => new Date(`${d}T00:00:00Z`).toLocaleDateString("en-IN", { dateStyle: "medium", timeZone: "UTC" });
const inr = (n) => Number(n || 0).toLocaleString("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 });
const lc = (v) => String(v ?? "").trim().toLowerCase();
const plural = (n, word) => `${n} ${word}${n === 1 ? "" : "s"}`;
const deals =$input.all().map((i) => i.json).filter((r) => r.client_name || r.deal_id);
const label = (r) => `${r.deal_id || "—"} · ${r.client_name || "?"}${r.title ? ` — ${r.title}` : ""}`;

const followUps = deals
  .filter((r) => lc(r.proposal_status) === "sent" && dayOf(r.proposal_follow_up_on) && dayOf(r.proposal_follow_up_on) <= today)
  .map((r) => `• ${label(r)}\n  Proposal sent ${dayOf(r.proposal_sent_on) ? nice(dayOf(r.proposal_sent_on)) : "?"} · follow-up due ${nice(dayOf(r.proposal_follow_up_on))}${r.value_inr ? ` · ${inr(r.value_inr)}` : ""}`);
const missingFollowUp = deals
  .filter((r) => lc(r.proposal_status) === "sent" && !dayOf(r.proposal_follow_up_on))
  .map((r) => `• ${label(r)} — no follow-up date set`);

const unpaid = deals.filter((r) => lc(r.invoice_status) === "unpaid" && dayOf(r.invoice_due_on));
const overdue = unpaid
  .filter((r) => dayOf(r.invoice_due_on) < today)
  .map((r) => `• ${label(r)}\n  Invoice ${r.invoice_number || "?"} · ${inr(r.invoice_amount_inr)} · due ${nice(dayOf(r.invoice_due_on))} · ${plural(daysBetween(today, dayOf(r.invoice_due_on)), "day")} overdue`);
const dueSoon = unpaid
  .filter((r) => { const d = daysBetween(dayOf(r.invoice_due_on), today); return d >= 0 && d <= 3; })
  .map((r) => `• ${label(r)}\n  Invoice ${r.invoice_number || "?"} · ${inr(r.invoice_amount_inr)} · due ${nice(dayOf(r.invoice_due_on))}`);

const sections = [
  ["Overdue invoices", overdue],
  ["Invoices due in the next 3 days", dueSoon],
  ["Proposals due a follow-up", followUps],
  ["Sent proposals without a follow-up date", missingFollowUp],
].filter(([, list]) => list.length);

if (!sections.length) return [];

const parts = [overdue.length && `${overdue.length} overdue`, dueSoon.length && `${dueSoon.length} due soon`, followUps.length && `${followUps.length} follow-up${followUps.length > 1 ? "s" : ""}`].filter(Boolean);
return [{
  json: {
    subject: `Deals today — ${parts.join(" · ") || "check follow-up dates"}`,
    body: [
      ...sections.flatMap(([title, list]) => [title.toUpperCase(), ...list, ""]),
      "Any client reminders due today are saved in Gmail → Drafts for you to review. Nothing is sent automatically.",
      'Update the row in n8n → Data tables → "TW Deals — proposals & invoices" (e.g. invoice_status = paid, proposal_status = accepted) to stop reminders.',
    ].join("\n"),
  },
}];

// Client drafts, never sent: proposal follow-up on its date (then weekly), invoice reminder 1 day overdue (then weekly).

const IST_MS = 330 * 60000;
const dayOf = (v) => {
  if (!v) return null;
  const t = Date.parse(v);
  return Number.isFinite(t) ? new Date(t + IST_MS).toISOString().slice(0, 10) : null;
};
const today = new Date(Date.now() + IST_MS).toISOString().slice(0, 10);
const daysBetween = (a, b) => Math.round((Date.parse(a) - Date.parse(b)) / 864e5);
const nice = (d) => new Date(`${d}T00:00:00Z`).toLocaleDateString("en-IN", { dateStyle: "medium", timeZone: "UTC" });
const inr = (n) => Number(n || 0).toLocaleString("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 });
const lc = (v) => String(v ?? "").trim().toLowerCase();
const plural = (n, word) => `${n} ${word}${n === 1 ? "" : "s"}`;
const deals =$input.all().map((i) => i.json).filter((r) => r.client_name || r.deal_id);
const first = (name) => String(name || "").trim().split(/\s+/)[0] || "there";
const due = (days) => days === 0 || (days > 0 && days % 7 === 0);
const drafts = [];

for (const r of deals) {
  if (!r.client_email) continue;
  const follow = dayOf(r.proposal_follow_up_on);
  if (lc(r.proposal_status) === "sent" && follow && follow <= today && due(daysBetween(today, follow))) {
    drafts.push({
      to: r.client_email,
      subject: `Following up: ${r.title || "our proposal"}`,
      body: [
        `Hi ${first(r.client_name)},`,
        "",
        `I wanted to follow up on the proposal we sent${dayOf(r.proposal_sent_on) ? ` on ${nice(dayOf(r.proposal_sent_on))}` : ""}${r.title ? ` for ${r.title}` : ""}. Do you have any questions, or would it help to talk it through? We're happy to adjust the scope if anything doesn't quite fit.`,
        "",
        "Best regards,",
        "TurtleWorks",
      ].join("\n"),
    });
  }
  const dueOn = dayOf(r.invoice_due_on);
  if (lc(r.invoice_status) === "unpaid" && dueOn && dueOn < today) {
    const late = daysBetween(today, dueOn);
    if (late === 1 || late % 7 === 0) {
      drafts.push({
        to: r.client_email,
        subject: `Invoice ${r.invoice_number || ""} — payment reminder`.replace("  ", " "),
        body: [
          `Hi ${first(r.client_name)},`,
          "",
          `A friendly reminder that invoice ${r.invoice_number || ""} for ${inr(r.invoice_amount_inr)}${r.title ? ` (${r.title})` : ""} was due on ${nice(dueOn)}. If it has already been paid, thank you — please ignore this note. Otherwise, could you let us know when we can expect payment?`.replace("  ", " "),
          "",
          "Best regards,",
          "TurtleWorks",
        ].join("\n"),
      });
    }
  }
}

return drafts.map((json) => ({ json }));

// TurtleWorks branded email layout: forest-green header band with the logo and name,
// white body, quiet footer. Table-based with inline styles so it survives Gmail, Outlook
// and phone mail apps. Pure function, no dependencies, so the exact same source is
// embedded into the n8n Code nodes (see build-emails.mjs) and unit-tested here.
// Every string a visitor can influence is escaped; only https, mailto and tel links are emitted.

const PALETTE = {
  forest: "#15382e",
  evergreen: "#1d5b46",
  ivory: "#f7f5ef",
  amber: "#c58a2e",
  mint: "#dcebe4",
  ink: "#17211d",
  slate: "#4a5a53",
  footer: "#f5f6f5",
  box: "#f4f7f5",
  outer: "#eef1ef",
  line: "#d5dcd8",
};

const BRAND = {
  name: "TurtleWorks",
  tagline: "Business Solutions & Technology Partner",
  site: "https://www.turtleworks.in",
  siteLabel: "turtleworks.in",
  email: "hello@turtleworks.in",
  logo: "https://www.turtleworks.in/brand/turtleworks-mark.png",
};

const FONT = "Arial,Helvetica,sans-serif";

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function safeUrl(value) {
  const url = String(value ?? "").trim();
  if (!url || /[\s"'<>`\\]/.test(url)) return null;
  if (/^https:\/\/[^/]+/i.test(url)) {
    try {
      return new URL(url).protocol === "https:" ? url : null;
    } catch {
      return null;
    }
  }
  if (/^mailto:[^\s@]+@[^\s@]+$/i.test(url)) return url;
  if (/^tel:\+?[0-9()-]{6,20}$/i.test(url)) return url;
  return null;
}

function paragraphsFrom(text) {
  return String(text ?? "")
    .replace(/\r\n?/g, "\n")
    .split(/\n{2,}/)
    .map((p) => p.trim())
    .filter(Boolean);
}

const text = (value) => escapeHtml(value).replace(/\n/g, "<br>");
const clip = (value, max) => String(value ?? "").replace(/\s+/g, " ").trim().slice(0, max);

function renderEmail({ preheader = "", title = "", greeting = "", paragraphs = [], reference = null, cta = null, footerNote = "", optOut = false } = {}) {
  const P = PALETTE;
  const href = cta ? safeUrl(cta.url) : null;

  const preview = clip(preheader, 140);
  const previewBlock = preview
    ? `<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent;mso-hide:all;">${escapeHtml(preview)}${"&#847;&zwnj;&nbsp;".repeat(30)}</div>`
    : "";

  const greetingBlock = greeting
    ? `<p style="margin:0 0 16px;font-family:${FONT};font-size:16px;line-height:26px;color:${P.ink};">${text(greeting)}</p>`
    : "";

  const bodyBlocks = paragraphs
    .filter((p) => String(p ?? "").trim())
    .map((p) => `<p style="margin:0 0 16px;font-family:${FONT};font-size:16px;line-height:26px;color:${P.ink};">${text(p)}</p>`)
    .join("");

  const referenceBlock =
    reference && reference.value
      ? `<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="margin:8px 0 20px;"><tr><td style="background:${P.box};border:1px solid ${P.line};border-radius:8px;padding:14px 18px;font-family:${FONT};font-size:13px;line-height:20px;color:${P.slate};">${text(reference.label || "Reference")}<br><strong style="font-size:16px;color:${P.ink};letter-spacing:0.2px;">${text(reference.value)}</strong></td></tr></table>`
      : "";

  const buttonBlock =
    cta && href
      ? `<table role="presentation" class="btn" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 24px;"><tr><td style="background:${P.evergreen};border-radius:8px;"><a href="${escapeHtml(href)}" style="display:inline-block;padding:14px 26px;font-family:${FONT};font-size:15px;font-weight:bold;line-height:20px;color:${P.ivory};text-decoration:none;border-radius:8px;">${text(cta.label)}</a></td></tr></table>`
      : "";

  const why = footerNote ? clip(footerNote, 240) : "You are receiving this email because you contacted TurtleWorks.";
  const stop = optOut ? `<br>Prefer not to hear from us? Reply STOP and we won't email you again.` : "";

  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="x-apple-disable-message-reformatting">
<meta name="color-scheme" content="light">
<meta name="supported-color-schemes" content="light">
<title>${escapeHtml(clip(title, 120) || BRAND.name)}</title>
<style>@media only screen and (max-width:620px){.container{width:100%!important}.px{padding-left:20px!important;padding-right:20px!important}.btn,.btn td,.btn a{display:block!important;text-align:center!important}}</style>
</head>
<body style="margin:0;padding:0;background:${P.outer};">
${previewBlock}
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${P.outer};"><tr><td align="center" style="padding:24px 12px;">
<table role="presentation" class="container" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px;background:#ffffff;border:1px solid ${P.line};border-radius:10px;overflow:hidden;">
<tr><td class="px" style="background:${P.forest};padding:26px 32px;border-bottom:3px solid ${P.amber};">
<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>
<td style="padding-right:14px;vertical-align:middle;"><img src="${BRAND.logo}" width="44" height="44" alt="${BRAND.name} logo" style="display:block;width:44px;height:44px;border:0;border-radius:9px;background:${P.ivory};"></td>
<td style="vertical-align:middle;font-family:${FONT};font-size:22px;line-height:26px;font-weight:bold;letter-spacing:-0.3px;color:${P.ivory};">${BRAND.name}<br><span style="font-size:12px;line-height:18px;font-weight:normal;letter-spacing:0;color:${P.mint};">${escapeHtml(BRAND.tagline)}</span></td>
</tr></table>
</td></tr>
<tr><td class="px" style="padding:36px 32px 12px;">
${greetingBlock}${bodyBlocks}${referenceBlock}${buttonBlock}
</td></tr>
<tr><td class="px" style="background:${P.footer};border-top:1px solid ${P.line};padding:24px 32px;font-family:${FONT};font-size:12px;line-height:19px;color:${P.slate};">
<strong style="color:${P.ink};">${BRAND.name}</strong> &middot; ${escapeHtml(BRAND.tagline)}<br>
<a href="${BRAND.site}" style="color:${P.evergreen};text-decoration:underline;">${BRAND.siteLabel}</a> &middot; <a href="mailto:${BRAND.email}" style="color:${P.evergreen};text-decoration:underline;">${BRAND.email}</a><br>
<span style="display:block;padding-top:10px;">${escapeHtml(why)}${stop}</span>
</td></tr>
</table>
</td></tr></table>
</body>
</html>`;
}

return { json: { ...$json, body_html: renderEmail({
  preheader: $json.subject,
  title: $json.subject,
  paragraphs: paragraphsFrom($json.body),
  footerNote: "You are receiving this email because of your proposal or invoice with TurtleWorks.",
}) } };
